import csv, re
from collections import defaultdict

ttl = open(GRAPH_TTL).read()

# Build a triple store from the TTL. The file is line-oriented N3-ish.
# Each triple line ends with '.' and properties joined by ';'
# Let's split into statements per subject block.

# Simpler: parse line by line. A statement: "subj pred obj ;" then "pred obj ;"...
# We'll gather blocks.

triples = []
cur = None  # dict of props
cur_s = None

def flush():
    global cur
    if cur and cur_s:
        for p, o in cur.items():
            triples.append((cur_s, p, o))
    cur = None
    cur_s = None

for line in ttl.splitlines():
    s = line.strip()
    if not s:
        continue
    if s.startswith('@') or s.startswith('<http'):  # prefix
        continue
    if ' :' in s and (' a ' in s or 'brick:' in s or 'rdfs:' in s or 'bldg:' in s or 'http' in s or 'ref:' in s):
        if cur is None:
            # start a new block
            # first triple on this line
            # split at ' a ' or ' '
            # Actually let's split by the first two whitespace-bounded tokens where the middle is a predicate.
            # Predicates typically contain ':'
            toks = s.split()
            # find predicate index: typically the token containing ':' that follows the subject
            if toks[1].startswith('a') and not toks[1].startswith('a:'):
                # 'subj a obj ;'
                subj = toks[0]
                pred = 'rdf:type'
                obj = toks[2].rstrip(';')
                obj = obj.rstrip('.')
                if cur is None:
                    cur = {}
                    cur_s = subj
                cur[pred] = obj
            else:
                # generic: subj pred obj ;
                if len(toks) >= 3:
                    subj = toks[0]
                    pred = toks[1].rstrip(';')
                    obj = toks[2].rstrip(' ;.')
                    if cur is None:
                        cur = {}
                        cur_s = subj
                    cur[pred] = obj
                else:
                    flush()
        else:
            # continuation line
            toks = s.split()
            if len(toks) >= 3:
                pred = toks[0].rstrip(';')
                obj = ' '.join(toks[1:]).rstrip(';')
                obj = obj.rstrip('.')
                cur[pred] = obj
            elif s.endswith(';'):
                continue
            else:
                # maybe final object
                obj = s.rstrip(';')
                if cur is not None:
                    # use last key? No, this is a new triple - but we lost the pred
                    # Actually a continuation line "pred obj;" has 2+ tokens
                    pass
    if s.endswith(' .') or s.endswith('.') and not s.endswith(';'):
        pass

# Above is too fragile. Let me do a simpler approach: extract from the TTL all statements involving Zone_Electric_Power_Sensors with regex, and resolve their isPointOf and hasExternalReference.

print("Triples count:", len(triples))
# Show zone EPS statements
zone_eps_preds = defaultdict(list)
for s, p, o in triples:
    if 'Zone_' in s and 'Electric_Power_Sensor' in s:
        zone_eps_preds[s].append((p, o))
for k, v in zone_eps_preds.items():
    print(k, v)

